<?php $title = 'สินค้าและสต็อก'; require __DIR__.'/../layouts/header.php'; ?>
<div class="page-actions"><p>สินค้าในร้านและจำนวนคงเหลือ</p><?php if ($isAdmin): ?><a class="button" href="<?= e(route('products.create')) ?>">+ เพิ่มสินค้า</a><?php endif; ?></div>
<?php require __DIR__.'/../partials/messages.php'; ?>
<section class="card"><form class="filter-form" method="get"><label for="q">ค้นหาชื่อ / รหัสสินค้า</label><div class="filter-controls"><input id="q" name="q" value="<?= e($q) ?>"><?php if ($isAdmin): ?><select name="active" aria-label="สถานะ"><option value="">ทุกสถานะ</option value="1" <?= ($filters['active'] ?? '') === '1' ? 'selected' : '' ?>>เปิดขาย</option><option value="0" <?= ($filters['active'] ?? '') === '0' ? 'selected' : '' ?>>ปิดขาย</option></select><?php endif; ?><label class="checkbox"><input name="low_stock" type="checkbox" value="1" <?= isset($filters['low_stock']) ? 'checked' : '' ?>> ใกล้หมด</label><button>ค้นหา</button></div></form>
<div class="table-wrap"><table><thead><tr><th>สินค้า / SKU</th><?php if ($isAdmin): ?><th>ต้นทุน</th><?php endif; ?><th>ราคาขาย</th><th>คงเหลือ</th><th>สถานะ</th><?php if ($isAdmin): ?><th></th><?php endif; ?></tr></thead><tbody>
<?php foreach ($products as $product): ?><tr><td><?= e($product->name) ?><small><?= e($product->sku) ?></small></td><?php if ($isAdmin): ?><td><?= e($product->cost_price) ?></td><?php endif; ?><td><?= e($product->sell_price) ?></td><td><span class="badge <?= $product->stock_qty <= $product->min_stock ? 'warning' : 'good' ?>"><?= e($product->stock_qty) ?> <?= e($product->unit) ?></span></td><td><?= $product->is_active ? 'เปิดขาย' : 'ปิดขาย' ?></td><?php if ($isAdmin): ?><td><a href="<?= e(route('products.show', $product)) ?>">สต็อก/ประวัติ</a> · <a href="<?= e(route('products.edit', $product)) ?>">แก้ไข</a></td><?php endif; ?></tr><?php endforeach; ?>
<?php if ($products->isEmpty()): ?><tr><td colspan="6" class="empty-state">ยังไม่มีสินค้าตามเงื่อนไข</td></tr><?php endif; ?></tbody></table></div><?php $paginator = $products; require __DIR__.'/../partials/pagination.php'; ?></section>
